import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.BjkiRu3Q.js";const o="/images/super-admin/image-18.png",e="/images/super-admin/image-19.png",d="/images/super-admin/image-20.png",n="/images/super-admin/image-21.png",h="/images/super-admin/image-22.png",s="/images/super-admin/image-23.png",p="/images/super-admin/image-24.png",g="/images/super-admin/image-25.png",b="/images/super-admin/image-26.png",P=JSON.parse('{"title":"4. 홈 화면 구성 및 관리","description":"","frontmatter":{},"headers":[],"relativePath":"home.md","filePath":"home.md"}'),c={name:"home.md"};function m(_,t,u,q,x,f){return l(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="_4-홈-화면-구성-및-관리" tabindex="-1">4. 홈 화면 구성 및 관리 <a class="header-anchor" href="#_4-홈-화면-구성-및-관리" aria-label="Permalink to &quot;4. 홈 화면 구성 및 관리&quot;">​</a></h1><p>홈 화면은 방문객이 축제 및 행사 안내 페이지에서 주요 정보와 서비스를 확인할 수 있는 공간입니다.</p><p>프로젝트 운영자는 CMS를 통해 메인 배너, 하이라이트, 바로가기, 하단 푸터 등을 설정하여 행사 특성에 맞는 홈 화면을 구성할 수 있습니다.</p><p>각 구성 요소는 개별 관리 메뉴에서 등록하거나 수정할 수 있으며, 변경한 내용은 저장 후 방문객용 안내 페이지에서 확인할 수 있습니다.</p><h2 id="_4-1-홈-화면-관리-메뉴" tabindex="-1">4.1. 홈 화면 관리 메뉴 <a class="header-anchor" href="#_4-1-홈-화면-관리-메뉴" aria-label="Permalink to &quot;4.1. 홈 화면 관리 메뉴&quot;">​</a></h2><p>홈 화면의 각 구성 요소는 프로젝트 관리 화면에서 개별 메뉴를 통해 관리합니다.</p><table tabindex="0"><thead><tr><th>메뉴</th><th>설명</th></tr></thead><tbody><tr><td>메인 배너</td><td>홈 화면에 표시할 대표 이미지 및 연결 링크 관리</td></tr><tr><td>하이라이트</td><td>방문객에게 강조할 주요 행사 일정 및 콘텐츠 설정</td></tr><tr><td>바로가기</td><td>주요 서비스나 페이지로 이동하는 바로가기 메뉴 관리</td></tr><tr><td>하단 푸터</td><td>홈 화면 하단에 표시할 이미지 및 배경색 설정</td></tr></tbody></table><p><img src="'+o+'" alt="image.png"></p><blockquote><p><strong>참고</strong></p><p>홈 화면에 표시되는 구성 요소는 프로젝트 설정에 따라 달라질 수 있습니다.</p><p>각 메뉴에서 콘텐츠를 등록한 후 방문객용 안내 페이지에서 정상적으로 표시되는지 확인해 주세요.</p></blockquote><hr><h2 id="_4-2-메인-배너-관리" tabindex="-1">4.2. 메인 배너 관리 <a class="header-anchor" href="#_4-2-메인-배너-관리" aria-label="Permalink to &quot;4.2. 메인 배너 관리&quot;">​</a></h2><p>메인 배너는 홈 화면에서 행사의 대표 이미지나 주요 안내 사항을 보여주는 영역입니다.</p><p>여러 개의 배너를 등록할 수 있으며, 배너별 이미지, 연결 링크 및 표시 순서를 설정할 수 있습니다.</p><h3 id="_1-메인-배너-관리-화면-이동" tabindex="-1">① 메인 배너 관리 화면 이동 <a class="header-anchor" href="#_1-메인-배너-관리-화면-이동" aria-label="Permalink to &quot;① 메인 배너 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>메인 배너</strong> 메뉴를 선택합니다.</li><li>현재 등록된 배너 목록을 확인합니다.</li><li>새로운 배너를 추가하거나 기존 배너를 수정할 수 있습니다.</li></ol><p><img src="'+e+'" alt="image.png"></p><h3 id="_2-메인-배너-등록" tabindex="-1">② 메인 배너 등록 <a class="header-anchor" href="#_2-메인-배너-등록" aria-label="Permalink to &quot;② 메인 배너 등록&quot;">​</a></h3><p><strong>등록 방법</strong></p><ol><li><strong>배너 이미지</strong> 영역에서 이미지 파일을 선택합니다.</li><li>등록할 이미지가 올바른지 확인합니다.</li><li><strong>추가</strong> 버튼을 클릭합니다.</li><li>추가된 배너에 필요한 연결 링크를 설정합니다.</li><li>화면 상단의 <strong>저장</strong> 버튼을 클릭합니다.</li></ol><p><strong>권장 이미지 규격</strong></p><table tabindex="0"><thead><tr><th>항목</th><th>권장 사양</th></tr></thead><tbody><tr><td>가로 크기</td><td>1080px</td></tr><tr><td>세로 크기</td><td>610px</td></tr><tr><td>최대 파일 크기</td><td>10MB</td></tr></tbody></table><p>이미지는 가로형 이미지 사용을 권장합니다.</p><h3 id="_3-배너-연결-링크-설정" tabindex="-1">③ 배너 연결 링크 설정 <a class="header-anchor" href="#_3-배너-연결-링크-설정" aria-label="Permalink to &quot;③ 배너 연결 링크 설정&quot;">​</a></h3><p>배너를 클릭했을 때 이동할 페이지를 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>링크 유형</th><th>설명</th></tr></thead><tbody><tr><td>없음</td><td>배너 클릭 시 별도의 페이지로 이동하지 않음</td></tr><tr><td>내부 링크</td><td>안내 페이지 내 다른 화면으로 이동</td></tr><tr><td>외부 링크</td><td>지정한 외부 웹사이트로 이동</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li>등록된 배너의 <strong>링크 유형</strong> 항목을 확인합니다.</li><li>원하는 링크 유형을 선택합니다.</li><li>내부 링크의 경우 이동할 내부 경로를 지정합니다.</li><li>외부 링크의 경우 이동할 URL을 입력합니다.</li><li>변경 내용을 저장합니다.</li></ol><blockquote><p><strong>참고</strong></p><p>외부 링크를 설정할 경우 <code>https://</code>를 포함한 전체 주소를 입력하는 것을 권장합니다.</p></blockquote><h3 id="_4-배너-순서-변경" tabindex="-1">④ 배너 순서 변경 <a class="header-anchor" href="#_4-배너-순서-변경" aria-label="Permalink to &quot;④ 배너 순서 변경&quot;">​</a></h3><p>등록된 배너는 드래그하여 표시 순서를 변경할 수 있습니다.</p><ol><li>순서를 변경할 배너를 선택합니다.</li><li>배너의 순서 변경 영역을 드래그합니다.</li><li>원하는 위치로 이동합니다.</li><li>변경된 순서를 확인한 후 저장합니다.</li></ol><p><img src="'+d+'" alt="image.png"></p><h3 id="_5-배너-수정-및-삭제" tabindex="-1">⑤ 배너 수정 및 삭제 <a class="header-anchor" href="#_5-배너-수정-및-삭제" aria-label="Permalink to &quot;⑤ 배너 수정 및 삭제&quot;">​</a></h3><p>기존 배너의 이미지를 변경하거나 불필요한 배너를 삭제할 수 있습니다.</p><p><strong>이미지 변경</strong></p><ol><li>변경할 배너의 <strong>이미지 변경</strong> 버튼을 클릭합니다.</li><li>새로운 이미지 파일을 선택합니다.</li><li>변경 내용을 저장합니다.</li></ol><p><strong>배너 삭제</strong></p><ol><li>삭제할 배너의 삭제 버튼을 클릭합니다.</li><li>삭제할 배너가 올바른지 확인합니다.</li><li>변경 내용을 저장합니다.</li></ol><hr><h2 id="_4-3-하이라이트-관리" tabindex="-1">4.3. 하이라이트 관리 <a class="header-anchor" href="#_4-3-하이라이트-관리" aria-label="Permalink to &quot;4.3. 하이라이트 관리&quot;">​</a></h2><p>하이라이트는 행사 일정 콘텐츠 중 조회수가 높은 콘텐츠를 홈 화면에 우선적으로 노출하는 기능입니다.</p><p>콘텐츠별 실제 조회수와 관리자가 설정한 가중치를 합산하여 노출 순위를 결정합니다.</p><p>이를 통해 방문객의 관심도가 높은 일정을 자동으로 노출하거나, 운영자가 특별히 홍보하고 싶은 일정을 우선적으로 노출할 수 있습니다.</p><h3 id="_1-하이라이트-관리-화면-이동" tabindex="-1">① 하이라이트 관리 화면 이동 <a class="header-anchor" href="#_1-하이라이트-관리-화면-이동" aria-label="Permalink to &quot;① 하이라이트 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>하이라이트</strong> 메뉴를 선택합니다.</li><li>등록된 행사 일정 목록과 현재 설정된 가중치를 확인합니다.</li><li>필요에 따라 표시 개수와 콘텐츠별 가중치를 설정합니다.</li></ol><p><img src="'+n+'" alt="image.png"></p><h3 id="_2-하이라이트-표시-개수-설정" tabindex="-1">② 하이라이트 표시 개수 설정 <a class="header-anchor" href="#_2-하이라이트-표시-개수-설정" aria-label="Permalink to &quot;② 하이라이트 표시 개수 설정&quot;">​</a></h3><p>홈 화면에 표시할 하이라이트 콘텐츠의 개수를 설정합니다.</p><p>설정한 개수만큼 조회수 순위가 높은 콘텐츠가 홈 화면에 노출됩니다.</p><h3 id="_3-콘텐츠별-가중치-설정" tabindex="-1">③ 콘텐츠별 가중치 설정 <a class="header-anchor" href="#_3-콘텐츠별-가중치-설정" aria-label="Permalink to &quot;③ 콘텐츠별 가중치 설정&quot;">​</a></h3><p>가중치는 특정 콘텐츠를 홈 화면에 우선적으로 노출하기 위해 부여하는 추가 조회수입니다.</p><p><strong>하이라이트 노출 기준</strong></p><p><code>노출 기준 조회수 = 실제 조회수 + 설정 가중치</code></p><p>예를 들어 다음과 같이 설정한 경우:</p><table tabindex="0"><thead><tr><th>콘텐츠</th><th>실제 조회수</th><th>가중치</th><th>노출 기준 조회수</th></tr></thead><tbody><tr><td>개막식 공연</td><td>300</td><td>1,000</td><td>1,300</td></tr><tr><td>푸드트럭 행사</td><td>850</td><td>0</td><td>850</td></tr><tr><td>버스킹 공연</td><td>500</td><td>200</td><td>700</td></tr><tr><td>체험 프로그램</td><td>600</td><td>0</td><td>600</td></tr></tbody></table><p>하이라이트 표시 개수를 3개로 설정했다면 다음 순서로 노출됩니다.</p><ol><li>개막식 공연 (1,300)</li><li>푸드트럭 행사 (850)</li><li>버스킹 공연 (700)</li></ol><p>실제 조회수가 낮더라도 높은 가중치를 부여하면 하이라이트에 우선적으로 노출할 수 있습니다.</p><h3 id="_4-하이라이트-활용-예시" tabindex="-1">④ 하이라이트 활용 예시 <a class="header-anchor" href="#_4-하이라이트-활용-예시" aria-label="Permalink to &quot;④  하이라이트 활용 예시&quot;">​</a></h3><p>하이라이트 기능은 다음과 같은 상황에서 활용할 수 있습니다.</p><ul><li><strong>주요 공연 홍보:</strong> 개막식이나 특별 공연에 높은 가중치를 부여하여 우선 노출</li><li><strong>신규 프로그램 홍보:</strong> 조회수가 적은 신규 콘텐츠에 가중치를 부여하여 노출 기회 확대</li><li><strong>인기 콘텐츠 안내:</strong> 별도의 가중치 없이 실제 조회수가 높은 콘텐츠를 우선 노출</li></ul><p>행사의 운영 목적에 맞게 가중치를 조정하면 방문객의 관심도와 운영자의 홍보 우선순위를 함께 반영할 수 있습니다.</p><hr><h2 id="_4-4-바로가기-관리" tabindex="-1">4.4. 바로가기 관리 <a class="header-anchor" href="#_4-4-바로가기-관리" aria-label="Permalink to &quot;4.4. 바로가기 관리&quot;">​</a></h2><p>바로가기는 방문객이 주요 서비스나 외부 페이지에 빠르게 접근할 수 있도록 제공하는 기능입니다.</p><p>바로가기에는 이미지, 이름 및 연결 링크를 설정할 수 있습니다.</p><h3 id="_1-바로가기-관리-화면-이동" tabindex="-1">① 바로가기 관리 화면 이동 <a class="header-anchor" href="#_1-바로가기-관리-화면-이동" aria-label="Permalink to &quot;① 바로가기 관리 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>바로가기</strong> 메뉴를 선택합니다.</li><li>현재 등록된 바로가기 목록을 확인합니다.</li><li>필요한 경우 새로운 바로가기 항목을 추가합니다.</li></ol><p><img src="'+h+'" alt="image.png"></p><h3 id="_2-바로가기-기본-설정" tabindex="-1">② 바로가기 기본 설정 <a class="header-anchor" href="#_2-바로가기-기본-설정" aria-label="Permalink to &quot;② 바로가기 기본 설정&quot;">​</a></h3><p>바로가기 영역의 홈 화면 표시 여부와 타이틀을 설정할 수 있습니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>홈 화면 표시</td><td>홈 화면에 바로가기 영역을 표시할지 설정</td></tr><tr><td>타이틀</td><td>바로가기 영역에 표시되는 제목</td></tr></tbody></table><p><strong>설정 방법</strong></p><ol><li><strong>홈 화면 표시</strong> 항목을 활성화합니다.</li><li><strong>타이틀</strong> 항목에 표시할 제목을 입력합니다.</li><li>변경 내용을 저장합니다.</li></ol><h3 id="_3-바로가기-항목-등록" tabindex="-1">③ 바로가기 항목 등록 <a class="header-anchor" href="#_3-바로가기-항목-등록" aria-label="Permalink to &quot;③ 바로가기 항목 등록&quot;">​</a></h3><p>바로가기 항목별로 이미지, 이름 및 이동할 링크를 설정합니다.</p><table tabindex="0"><thead><tr><th>항목</th><th>설명</th></tr></thead><tbody><tr><td>이미지</td><td>바로가기 메뉴에 표시할 이미지</td></tr><tr><td>이름</td><td>바로가기 메뉴의 이름</td></tr><tr><td>링크 유형</td><td>내부 링크 또는 외부 링크 선택</td></tr><tr><td>내부 경로</td><td>안내 페이지 내 이동할 경로</td></tr><tr><td>URL</td><td>외부 웹사이트의 접속 주소</td></tr></tbody></table><p><strong>등록 방법</strong></p><ol><li>바로가기 추가 영역으로 이동합니다.</li><li>사용할 이미지를 등록합니다.</li><li>바로가기 이름을 입력합니다.</li><li>링크 유형을 선택합니다.</li><li>내부 경로 또는 외부 URL을 설정합니다.</li><li><strong>추가</strong> 버튼을 클릭합니다.</li><li>등록된 항목을 확인한 후 화면 상단의 <strong>저장</strong> 버튼을 클릭합니다.</li></ol><p><strong>권장 이미지 규격</strong></p><table tabindex="0"><thead><tr><th>항목</th><th>권장 사양</th></tr></thead><tbody><tr><td>가로 크기</td><td>240px</td></tr><tr><td>세로 크기</td><td>240px</td></tr><tr><td>최대 파일 크기</td><td>2MB</td></tr></tbody></table><p><img src="'+s+'" alt="image.png"></p><h3 id="_4-바로가기-수정-및-삭제" tabindex="-1">④ 바로가기 수정 및 삭제 <a class="header-anchor" href="#_4-바로가기-수정-및-삭제" aria-label="Permalink to &quot;④ 바로가기 수정 및 삭제&quot;">​</a></h3><p><strong>바로가기 수정</strong></p><ol><li>수정할 바로가기 항목의 수정 버튼을 클릭합니다.</li><li>이미지, 이름 또는 링크를 변경합니다.</li><li><strong>수정</strong> 버튼을 클릭합니다.</li><li>변경된 내용을 저장합니다.</li></ol><p><strong>바로가기 삭제</strong></p><ol><li>삭제할 항목의 삭제 버튼을 클릭합니다.</li><li>삭제 확인 창이 표시되면 내용을 확인합니다.</li><li>삭제를 진행합니다.</li><li>변경 내용을 저장합니다.</li></ol><h3 id="_5-바로가기-활용-예시" tabindex="-1">⑤ 바로가기 활용 예시 <a class="header-anchor" href="#_5-바로가기-활용-예시" aria-label="Permalink to &quot;⑤ 바로가기 활용 예시&quot;">​</a></h3><table tabindex="0"><thead><tr><th>바로가기 이름</th><th>활용 목적</th></tr></thead><tbody><tr><td>행사 일정</td><td>공연 및 프로그램 일정으로 이동</td></tr><tr><td>행사장 지도</td><td>투어맵 화면으로 이동</td></tr><tr><td>스탬프 투어</td><td>스탬프 투어 참여 화면으로 이동</td></tr><tr><td>공식 홈페이지</td><td>행사 공식 웹사이트로 이동</td></tr><tr><td>교통 안내</td><td>외부 교통 정보 페이지로 이동</td></tr></tbody></table><blockquote><p><strong>참고</strong></p><p>내부 링크를 이용하면 안내 페이지 내 주요 기능으로 이동할 수 있습니다.</p><p>외부 링크는 별도의 웹사이트로 이동하는 경우에 사용합니다.</p></blockquote><hr><h2 id="_4-5-하단-푸터-관리" tabindex="-1">4.5. 하단 푸터 관리 <a class="header-anchor" href="#_4-5-하단-푸터-관리" aria-label="Permalink to &quot;4.5. 하단 푸터 관리&quot;">​</a></h2><p>하단 푸터는 홈 화면의 가장 아래쪽에 표시되는 이미지 영역입니다.</p><p>푸터 이미지와 배경색을 설정하여 홈 화면 하단의 디자인을 구성할 수 있습니다.</p><h3 id="_1-하단-푸터-설정-화면-이동" tabindex="-1">① 하단 푸터 설정 화면 이동 <a class="header-anchor" href="#_1-하단-푸터-설정-화면-이동" aria-label="Permalink to &quot;① 하단 푸터 설정 화면 이동&quot;">​</a></h3><ol><li>프로젝트 관리 화면에서 <strong>하단 푸터</strong> 메뉴를 선택합니다.</li><li>현재 설정된 이미지와 배경색을 확인합니다.</li></ol><p><img src="'+p+'" alt="image.png"></p><h3 id="_2-홈-화면-표시-설정" tabindex="-1">② 홈 화면 표시 설정 <a class="header-anchor" href="#_2-홈-화면-표시-설정" aria-label="Permalink to &quot;② 홈 화면 표시 설정&quot;">​</a></h3><p><strong>홈 화면 표시</strong> 항목을 이용하여 푸터 영역의 표시 여부를 설정할 수 있습니다.</p><ul><li>활성화: 홈 화면에 푸터 영역 표시</li><li>비활성화: 홈 화면에서 푸터 영역 숨김</li></ul><h3 id="_3-푸터-이미지-등록" tabindex="-1">③ 푸터 이미지 등록 <a class="header-anchor" href="#_3-푸터-이미지-등록" aria-label="Permalink to &quot;③ 푸터 이미지 등록&quot;">​</a></h3><ol><li><strong>이미지 추가</strong> 영역에서 사용할 이미지 파일을 선택합니다.</li><li>등록된 이미지를 확인합니다.</li><li>필요한 경우 <strong>이미지 변경</strong>을 통해 다른 이미지로 교체합니다.</li><li>설정을 저장합니다.</li></ol><p>푸터 이미지는 홈 화면 하단에서 이미지 비율을 유지하면서 가로 너비에 맞춰 표시됩니다.</p><h3 id="_4-배경색-설정" tabindex="-1">④ 배경색 설정 <a class="header-anchor" href="#_4-배경색-설정" aria-label="Permalink to &quot;④ 배경색 설정&quot;">​</a></h3><p>푸터 이미지의 배경 또는 하단 여백 영역에 적용할 색상을 설정합니다.</p><p><strong>설정 방법</strong></p><ol><li><strong>배경색</strong> 항목으로 이동합니다.</li><li>원하는 색상을 선택합니다.</li><li>미리보기에서 적용된 모습을 확인합니다.</li><li>화면 상단의 <strong>저장</strong> 버튼을 클릭합니다.</li></ol><p>배경색은 PNG 이미지의 배경 또는 하단 여백 영역에 사용됩니다.</p><hr><h2 id="_4-6-홈-화면-구성-확인" tabindex="-1">4.6. 홈 화면 구성 확인 <a class="header-anchor" href="#_4-6-홈-화면-구성-확인" aria-label="Permalink to &quot;4.6. 홈 화면 구성 확인&quot;">​</a></h2><p>모든 홈 화면 콘텐츠의 설정을 완료한 후에는 방문객용 안내 페이지에서 실제 표시 상태를 확인합니다.</p><h3 id="_1-확인-방법" tabindex="-1">① 확인 방법 <a class="header-anchor" href="#_1-확인-방법" aria-label="Permalink to &quot;① 확인 방법&quot;">​</a></h3><ol><li>홈 화면에 사용할 콘텐츠의 등록 및 저장을 완료합니다.</li><li>방문객용 안내 페이지에 접속합니다.</li><li>홈 화면에 등록한 구성 요소가 표시되는지 확인합니다.</li><li>배너 및 바로가기의 연결 링크가 정상적으로 동작하는지 확인합니다.</li><li>모바일 화면에서 이미지와 텍스트가 잘리지 않는지 확인합니다.</li></ol><h3 id="_2-최종-점검-항목" tabindex="-1">② 최종 점검 항목 <a class="header-anchor" href="#_2-최종-점검-항목" aria-label="Permalink to &quot;② 최종 점검 항목&quot;">​</a></h3><ul><li>메인 배너 이미지가 정상적으로 표시되는지 확인</li><li>배너의 표시 순서가 올바른지 확인</li><li>배너 클릭 시 지정한 페이지로 이동하는지 확인</li><li>하이라이트에 원하는 일정이 표시되는지 확인</li><li>바로가기 이름과 이미지가 정상적으로 표시되는지 확인</li><li>바로가기 링크가 올바르게 연결되는지 확인</li><li>하단 푸터 이미지 및 배경색이 정상적으로 적용되는지 확인</li><li>모바일 화면에서 전체 구성이 자연스럽게 표시되는지 확인</li></ul><p><img src="'+g+'" alt="image.png"></p><p><img src="'+b+'" alt="image.png"></p>',117)])])}const y=a(c,[["render",m]]);export{P as __pageData,y as default};
